function run(selected_text) {
  return selected_text
    .split(/\r\n?|\n/)
    .filter((line) => !/^[ \t]*$/.test(line))
    .map((line) => {
      const indent = (line.match(/^[ \t]*/) || [""])[0];
      const content = line
        .slice(indent.length)
        .replace(/^(?:(?:[-+*]|\d+[.)])\s+)?(?:\[[ xX]\]\s+)?/, "")
        .trim();
      return indent + "- [ ] " + content;
    })
    .join("\n");
}
